import {HARNESS_RETURN_ERRORS} from './harness-return-errors.js';
// Localized errors keep stable protocol codes and legacy diagnostic aliases.
const locales=["en","zh-Hans","zh-Hant","ja","ru","de","fr","es"];
const rows=[
[["MODEL_PROGRESS_STALLED"], ["The model has stopped making progress. The task is not confirmed complete; you can continue or adjust your request.", "模型未能继续推进。任务尚未确认完成，可以继续或调整请求。", "模型未能繼續推進。任務尚未確認完成，可以繼續或調整要求。", "モデルが処理を進められませんでした。完了は未確認です。続行するか、依頼を調整してください。", "Модель перестала продвигаться. Завершение задачи не подтверждено. Можно продолжить или уточнить запрос.", "Das Modell kommt nicht weiter. Die Aufgabe ist noch nicht bestätigt abgeschlossen. Du kannst fortfahren oder die Anfrage anpassen.", "Le modèle ne progresse plus. La tâche n’est pas confirmée terminée. Vous pouvez continuer ou modifier la demande.", "El modelo ha dejado de avanzar. La tarea no está confirmada como completada. Puedes continuar o ajustar la solicitud."]],
[["DEVICE_CLIENT_CAPACITY"], ["The ESP32 bridge has reached its saved browser limit. Use a browser that has already connected to this bridge.", "ESP32 桥保存的浏览器连接已达上限，请使用之前连接过此桥的浏览器。", "ESP32 橋接器儲存的瀏覽器連線已達上限，請使用之前連線過此橋接器的瀏覽器。", "ESP32 ブリッジに保存できるブラウザ数の上限に達しました。以前接続したブラウザを使用してください。", "Достигнут лимит сохранённых браузеров моста ESP32. Используйте браузер, который уже подключался к этому мосту.", "Die ESP32-Bridge hat die Höchstzahl gespeicherter Browser erreicht. Verwende einen Browser, der bereits mit dieser Bridge verbunden war.", "La limite de navigateurs enregistrés sur le pont ESP32 est atteinte. Utilisez un navigateur déjà connecté à ce pont.", "El puente ESP32 alcanzó el límite de navegadores guardados. Usa un navegador que ya se haya conectado a este puente."]],
[["DEVICE_BOARD_BUSY"], ["The ESP32 bridge is busy. Wait a moment, then try again.", "ESP32 桥正忙，请稍后重试。", "ESP32 橋接器忙碌中，請稍後再試。", "ESP32 ブリッジが処理中です。しばらくしてから再試行してください。", "Мост ESP32 занят. Подождите немного и повторите попытку.", "Die ESP32-Bridge ist beschäftigt. Warte einen Moment und versuche es erneut.", "Le pont ESP32 est occupé. Patientez un instant, puis réessayez.", "El puente ESP32 está ocupado. Espera un momento y vuelve a intentarlo."]],
[["DEVICE_TARGET_BUSY"], ["The phone is busy with an input operation or connection test. Wait for it to finish, then try again.", "手机正在执行输入操作或连接测试，请等待完成后重试。", "手機正在執行輸入操作或連線測試，請等待完成後再試。", "端末で入力操作または接続テストを実行中です。完了後に再試行してください。", "На телефоне выполняется ввод или проверка подключения. Дождитесь завершения и повторите попытку.", "Auf dem Telefon läuft eine Eingabe oder ein Verbindungstest. Warte auf den Abschluss und versuche es erneut.", "Une saisie ou un test de connexion est en cours sur le téléphone. Attendez la fin, puis réessayez.", "El teléfono está realizando una entrada o una prueba de conexión. Espera a que termine y vuelve a intentarlo."]],
[["DEVICE_CHALLENGE_BUSY"], ["The input test is still finishing or was just run. Wait up to 30 seconds, then tap Start test again.", "输入测试尚未结束，或刚刚运行过。请最多等待 30 秒，再点“开始测试”。", "輸入測試尚未結束，或剛剛執行過。請最多等候 30 秒，再點「開始測試」。", "入力テストが実行中か、直前に実行されました。最大 30 秒待ってから、もう一度テストを開始してください。", "Проверка ввода ещё выполняется или только что завершилась. Подождите до 30 секунд и запустите её снова.", "Der Eingabetest läuft noch oder wurde gerade ausgeführt. Warte bis zu 30 Sekunden und starte den Test erneut.", "Le test de saisie est encore en cours ou vient d’être lancé. Attendez jusqu’à 30 secondes, puis relancez le test.", "La prueba de entrada sigue en curso o acaba de ejecutarse. Espera hasta 30 segundos y vuelve a iniciarla."]],
[["DEVICE_CONFLICT"], ["The bridge could not accept this request in its current state. Refresh the connection and try again.", "ESP32 桥当前无法接受此请求，请刷新连接后重试。", "ESP32 橋接器目前無法接受此請求，請重新整理連線後再試。", "ブリッジの現在の状態では、このリクエストを受け付けられません。接続を更新して再試行してください。", "Мост не может принять запрос в текущем состоянии. Обновите подключение и повторите попытку.", "Die Bridge kann diese Anfrage im aktuellen Zustand nicht annehmen. Aktualisiere die Verbindung und versuche es erneut.", "Le pont ne peut pas accepter cette requête dans son état actuel. Actualisez la connexion et réessayez.", "El puente no puede aceptar esta solicitud en su estado actual. Actualiza la conexión y vuelve a intentarlo."]],
[["DEVICE_RTC_CONFIG_INVALID", "DEVICE_RTC_CONFIG_UNAVAILABLE"], ["Open the bridge settings page to import its connection information.", "请打开桥设置页，导入连接信息。", "請開啟橋接器設定頁，匯入連線資訊。", "ブリッジの設定ページから接続情報を読み込んでください。", "Откройте настройки моста и импортируйте данные подключения.", "Öffne die Bridge-Einstellungen und importiere die Verbindungsdaten.", "Ouvrez les réglages du pont pour importer les informations de connexion.", "Abre los ajustes del puente e importa los datos de conexión."]],
[["DEVICE_RTC_CLOSED", "DEVICE_RTC_CONNECT_TIMEOUT", "DEVICE_RTC_CONNECT_FAILED", "DEVICE_RTC_DISCONNECTED", "DEVICE_RTC_TIMEOUT"], ["The ESP32 bridge is disconnected. Check its power and Wi-Fi, then reconnect.", "ESP32 桥已断开，请检查供电和 Wi-Fi 后重新连接。", "ESP32 橋接器已斷線，請檢查供電和 Wi-Fi 後重新連線。", "ESP32 ブリッジが切断されました。電源と Wi-Fi を確認して再接続してください。", "Мост ESP32 отключён. Проверьте питание и Wi-Fi и подключитесь снова.", "Die ESP32-Bridge ist getrennt. Prüfe Stromversorgung und WLAN und verbinde sie erneut.", "Le pont ESP32 est déconnecté. Vérifiez son alimentation et le Wi-Fi, puis reconnectez-le.", "El puente ESP32 está desconectado. Comprueba la alimentación y el Wi-Fi y vuelve a conectarlo."]],
[["DEVICE_RTC_PROTOCOL_ERROR", "DEVICE_RTC_SDP_INVALID"], ["The bridge connection failed. Refresh the page and reconnect the bridge.", "桥连接出错，请刷新页面后重新连接。", "橋接器連線發生錯誤，請重新整理頁面後再連線。", "ブリッジ接続でエラーが発生しました。ページを更新して再接続してください。", "Ошибка подключения моста. Обновите страницу и подключитесь снова.", "Die Bridge-Verbindung ist fehlgeschlagen. Lade die Seite neu und verbinde die Bridge erneut.", "La connexion au pont a échoué. Actualisez la page et reconnectez le pont.", "Falló la conexión al puente. Actualiza la página y vuelve a conectarlo."]],
[["DEVICE_RTC_BUSY"], ["The bridge is busy. Wait for the current request to finish.", "桥正在处理请求，请稍后重试。", "橋接器正在處理請求，請稍後再試。", "ブリッジが処理中です。しばらくしてから再試行してください。", "Мост занят. Дождитесь завершения текущего запроса.", "Die Bridge ist beschäftigt. Warte, bis die aktuelle Anfrage abgeschlossen ist.", "Le pont est occupé. Attendez la fin de la requête en cours.", "El puente está ocupado. Espera a que termine la solicitud actual."]],
[["DEVICE_RTC_UNSUPPORTED"], ["This browser does not support WebRTC connections. Open the site in Safari.", "此浏览器不支持 WebRTC 连接，请使用 Safari 打开。", "此瀏覽器不支援 WebRTC 連線，請使用 Safari 開啟。", "このブラウザは WebRTC 接続に対応していません。Safari で開いてください。", "Этот браузер не поддерживает WebRTC. Откройте сайт в Safari.", "Dieser Browser unterstützt keine WebRTC-Verbindungen. Öffne die Website in Safari.", "Ce navigateur ne prend pas en charge WebRTC. Ouvrez le site dans Safari.", "Este navegador no admite WebRTC. Abre el sitio en Safari."]],
[["DEVICE_CLIPBOARD_INVALID"], ["The clipboard transfer parameters are invalid. Prepare the text again.", "剪贴板传输参数无效，请重新准备文字。", "剪貼簿傳輸參數無效，請重新準備文字。", "クリップボード転送の設定が無効です。テキストを準備し直してください。", "Недопустимые параметры передачи текста. Подготовьте текст заново.", "Die Parameter für die Zwischenablage-Übertragung sind ungültig. Bereite den Text erneut vor.", "Les paramètres du transfert sont invalides. Préparez à nouveau le texte.", "Los parámetros de transferencia no son válidos. Prepara el texto de nuevo."]],

[["DEVICE_SETUP_UPGRADE_REQUIRED", "DEVICE_CONNECTION_CODE_REQUIRED", "DEVICE_CONNECTION_CODE_INVALID"], ["This device uses an older firmware. Update it on the flashing page to use the current connection setup.", "这台设备使用的是旧版固件，请在烧录页面更新后使用新的连接方式。", "這台裝置使用的是舊版韌體，請在燒錄頁面更新後使用新的連接方式。", "このデバイスのファームウェアは古いバージョンです。書き込みページで更新してください。", "На устройстве старая прошивка. Обновите её на странице прошивки, чтобы использовать новое подключение.", "Dieses Gerät verwendet ältere Firmware. Aktualisiere sie auf der Flash-Seite für die neue Verbindung.", "Cet appareil utilise un ancien firmware. Mettez-le à jour sur la page de flash pour utiliser la nouvelle connexion.", "Este dispositivo tiene un firmware antiguo. Actualízalo en la página de grabación para usar la nueva conexión."]],

[["CLIPBOARD_COPY_REQUIRED"],["The prepared text has not been copied for this phone. Return to the Harness and copy it before pasting.","准备的文字尚未为这台手机复制成功。请回到 Harness 完成复制后再粘贴。","準備的文字尚未為這台手機複製成功。請回到 Harness 完成複製後再貼上。","この電話用のテキストはまだコピーされていません。Harnessでコピーしてから貼り付けてください。","Подготовленный текст ещё не скопирован для этого телефона. Вернитесь в Harness и скопируйте его перед вставкой.","Der vorbereitete Text wurde für dieses Telefon noch nicht kopiert. Kopieren Sie ihn im Harness vor dem Einfügen.","Le texte préparé n’a pas encore été copié pour ce téléphone. Copiez-le dans le Harness avant de le coller.","El texto preparado aún no se ha copiado para este teléfono. Cópialo en el Harness antes de pegarlo."]],
[["CLIPBOARD_AWAITING_USER_ACTION"],["The text is ready. Return to the Harness and tap Copy and continue.","文字已准备好。请回到 Harness 点“复制并继续”。","文字已準備好。請回到 Harness 點「複製並繼續」。","テキストを準備しました。Harnessに戻って「コピーして続行」をタップしてください。","Текст подготовлен. Вернитесь в Harness и нажмите «Копировать и продолжить».","Der Text ist vorbereitet. Kehren Sie zum Harness zurück und tippen Sie auf „Kopieren und fortfahren“.","Le texte est prêt. Revenez au Harness et appuyez sur Copier et continuer.","El texto está preparado. Vuelve al Harness y pulsa Copiar y continuar."]],
[["DEVICE_BRIDGE_UNAVAILABLE"],["The ESP32 bridge is disconnected. Further phone input cannot be sent. Reconnect the bridge before continuing.","ESP32桥未连接，无法继续发送手机操作。请连接桥后继续。","ESP32橋未連線，無法繼續傳送手機操作。請連接橋後繼續。","ESP32ブリッジが未接続のため、操作を送信できません。接続してから続けてください。","Мост ESP32 не подключён. Дальнейшая отправка команд невозможна. Подключите мост, чтобы продолжить.","Die ESP32-Bridge ist nicht verbunden. Weitere Eingaben sind nicht möglich. Verbinden Sie die Bridge, um fortzufahren.","Le pont ESP32 est déconnecté. Impossible d’envoyer d’autres commandes au téléphone. Reconnectez-le pour continuer.","El puente ESP32 está desconectado. No se pueden enviar más órdenes al teléfono. Conecta el puente para continuar."]],
[["DEVICE_BLUETOOTH_UNAVAILABLE"],["The ESP32 bridge is connected, but its Bluetooth connection to this phone is unavailable. Reconnect Bluetooth before continuing.","ESP32桥已连接，但桥与手机的蓝牙连接不可用。请重新连接蓝牙后继续。","ESP32橋已連線，但橋與手機的藍牙連線無法使用。請重新連接藍牙後繼續。","ESP32ブリッジには接続済みですが、電話とのBluetooth接続がありません。Bluetoothを接続し直してください。","Мост ESP32 подключён, но Bluetooth-связь с телефоном недоступна. Восстановите её, чтобы продолжить.","Die ESP32-Bridge ist verbunden, aber die Bluetooth-Verbindung zum Telefon fehlt. Stellen Sie sie wieder her.","Le pont ESP32 est connecté, mais sa connexion Bluetooth au téléphone est indisponible. Rétablissez-la pour continuer.","El puente ESP32 está conectado, pero no tiene conexión Bluetooth con el teléfono. Vuelve a conectarlo para continuar."]],
[["DEVICE_INPUT_UNVERIFIED"],["The ESP32 bridge is connected. Complete the phone input test before sending commands.","ESP32桥已连接，请先完成手机输入的连接测试，再发送操作。","ESP32橋已連線，請先完成手機輸入的連線測試，再傳送操作。","ESP32ブリッジには接続済みです。操作する前に電話の入力テストを完了してください。","Мост ESP32 подключён. Перед отправкой команд выполните проверку ввода на телефоне.","Die ESP32-Bridge ist verbunden. Führen Sie vor dem Senden von Befehlen den Eingabetest am Telefon durch.","Le pont ESP32 est connecté. Effectuez le test de saisie sur le téléphone avant d’envoyer des commandes.","El puente ESP32 está conectado. Completa la prueba de entrada del teléfono antes de enviar órdenes."]],
[["PROVIDER_MODELS_HTTP"],["The model list could not be loaded. Check the address, access and CORS, or enter a model ID manually.","无法读取模型列表，请检查地址、权限和跨域访问，或手动填写模型 ID。","無法讀取模型清單，請檢查位址、權限和跨來源存取，或手動填寫模型 ID。","モデル一覧を取得できません。URL、権限、CORSを確認するか、モデルIDを手入力してください。","Не удалось загрузить список моделей. Проверьте адрес, доступ и CORS или введите ID модели вручную.","Die Modellliste konnte nicht geladen werden. Prüfen Sie Adresse, Zugriff und CORS oder geben Sie eine Modell-ID ein.","Impossible de charger les modèles. Vérifiez l’adresse, l’accès et CORS, ou saisissez un ID de modèle.","No se pudo cargar la lista de modelos. Revisa la dirección, los permisos y CORS, o introduce un ID manualmente."]],
[["PROVIDER_CREDENTIAL_MISSING"],["This API has no saved key. Open Settings → Accounts or APIs and enter its API key.","此 API 没有已保存的密钥，请前往“设置 → 账号或 API”填写 API 密钥。","此 API 沒有已儲存的金鑰，請前往「設定 → 帳號或 API」填寫 API 金鑰。","APIキーが保存されていません。「設定 → アカウントまたはAPI」でキーを入力してください。","Для этого API не сохранён ключ. Укажите его в «Настройки → Аккаунты или API».","Für diese API ist kein Schlüssel gespeichert. Tragen Sie ihn unter „Einstellungen → Konten oder APIs“ ein.","Aucune clé n’est enregistrée pour cette API. Saisissez-la dans Réglages → Comptes ou API.","Esta API no tiene una clave guardada. Introdúcela en Ajustes → Cuentas o API."]],
[["PROVIDER_CREDENTIAL_LOCKED"],["This API key was encrypted by an earlier version and is still locked. Open its settings and unlock it once, or enter the API key again. Your saved record has been kept.","此 API 密钥由旧版本加密保存，目前尚未解锁。请打开该 API 的设置，解锁一次或重新填写密钥；原有记录仍保留。","此 API 金鑰由舊版本加密儲存，目前尚未解鎖。請開啟該 API 的設定，解鎖一次或重新填寫金鑰；原有記錄仍保留。","以前のバージョンで暗号化されたAPIキーがロックされています。API設定で一度解除するか、キーを再入力してください。既存の記録は保持されています。","Ключ зашифрован предыдущей версией и заблокирован. Разблокируйте его в настройках API или введите заново. Прежняя запись сохранена.","Der API-Schlüssel wurde von einer früheren Version verschlüsselt. Entsperren Sie ihn einmal in den API-Einstellungen oder geben Sie ihn erneut ein. Der bisherige Eintrag bleibt erhalten.","Cette clé API a été chiffrée par une ancienne version. Déverrouillez-la une fois dans ses réglages ou saisissez-la à nouveau. L’enregistrement existant est conservé.","Una versión anterior cifró esta clave API y sigue bloqueada. Desbloquéala una vez en sus ajustes o vuelve a introducirla. El registro anterior se conserva."]],
[["PROVIDER_AUTH_REJECTED"],["The API endpoint rejected authentication. Check the key saved for this API and that it belongs to this endpoint.","API 端点拒绝了身份验证，请核对该 API 保存的密钥，以及密钥是否属于这个端点。","API 端點拒絕了身分驗證，請核對該 API 儲存的金鑰，以及金鑰是否屬於此端點。","APIエンドポイントが認証を拒否しました。保存されたキーと接続先の組み合わせを確認してください。","API отклонил аутентификацию. Проверьте сохранённый ключ и соответствие ключа адресу API.","Der API-Endpunkt hat die Anmeldung abgelehnt. Prüfen Sie den gespeicherten Schlüssel und ob er zu diesem Endpunkt gehört.","Le point de terminaison API a refusé l’authentification. Vérifiez la clé enregistrée et qu’elle correspond à ce point de terminaison.","El endpoint de la API rechazó la autenticación. Comprueba la clave guardada y que corresponda a ese endpoint."]],
[["PROVIDER_PAYMENT_REQUIRED"],["The API endpoint reported a billing or balance issue. Check billing for this API account.","API 端点报告账单或余额问题，请核对该 API 账号的账单。","API 端點回報帳單或餘額問題，請核對該 API 帳號的帳單。","APIで請求または残高の問題が報告されました。アカウントの請求情報を確認してください。","API сообщил о проблеме с оплатой или балансом. Проверьте платёжные данные аккаунта.","Der API-Endpunkt meldet ein Abrechnungs- oder Guthabenproblem. Prüfen Sie die Abrechnung dieses API-Kontos.","L’API signale un problème de facturation ou de solde. Vérifiez la facturation de ce compte API.","La API indica un problema de facturación o saldo. Revisa la facturación de esta cuenta."]],
[["PROVIDER_ACCESS_DENIED"],["The API endpoint denied access. Check this account’s permissions for the selected model.","API 端点拒绝访问，请检查该账号使用所选模型的权限。","API 端點拒絕存取，請檢查該帳號使用所選模型的權限。","APIへのアクセスが拒否されました。選択したモデルの利用権限を確認してください。","API запретил доступ. Проверьте права аккаунта на выбранную модель.","Der API-Endpunkt verweigert den Zugriff. Prüfen Sie die Berechtigung für das gewählte Modell.","L’API refuse l’accès. Vérifiez les droits du compte pour le modèle choisi.","La API denegó el acceso. Revisa los permisos de la cuenta para el modelo seleccionado."]],
[["PROVIDER_HTTP_ERROR"],["The AI request failed. Check the endpoint, credentials, quota and CORS access.","模型请求失败，请检查接口地址、凭据、额度和跨域访问。","模型請求失敗，請檢查介面位址、憑證、額度和跨來源存取。","AIリクエストに失敗しました。URL、認証情報、利用枠、CORSを確認してください。","Запрос ИИ не выполнен. Проверьте адрес, учётные данные, квоту и доступ CORS.","Die KI-Anfrage ist fehlgeschlagen. Prüfen Sie Endpunkt, Zugangsdaten, Kontingent und CORS-Zugriff.","La requête IA a échoué. Vérifiez l’adresse, les identifiants, le quota et l’accès CORS.","La solicitud de IA falló. Revisa la dirección, las credenciales, la cuota y el acceso CORS."]],
[["CONTEXT_BUDGET_INVALID","压缩目标与输出预留之和必须小于触发阈值。"],["Enter a valid context compaction threshold.","请填写有效的上下文压缩阈值。","請填寫有效的上下文壓縮門檻。","有効なコンテキスト圧縮のしきい値を入力してください。","Укажите допустимый порог сжатия контекста.","Geben Sie eine gültige Schwelle für die Kontextkomprimierung ein.","Saisissez un seuil de réduction du contexte valide.","Introduce un umbral válido de reducción del contexto."]],
[["DEVICE_REQUEST_TOO_LARGE","Compiled segment exceeds device request byte limit; shorten or sparsify the motion.","Compiled segment exceeds device limits"],["This gesture exceeds the device limit. Shorten it or reduce path points; it has not been sent.","此手势超过设备限制，请缩短时长或减少路径点；尚未发送。","此手勢超過裝置限制，請縮短時間或減少路徑點；尚未傳送。","操作がデバイスの上限を超えています。時間や経路点を減らしてください。送信していません。","Жест превышает лимит устройства. Сократите время или число точек; команда не отправлена.","Die Geste überschreitet das Gerätelimit. Verkürzen Sie sie oder reduzieren Sie die Pfadpunkte. Sie wurde nicht gesendet.","Ce geste dépasse la limite de l’appareil. Réduisez sa durée ou ses points. Il n’a pas été envoyé.","El gesto supera el límite del dispositivo. Acórtalo o reduce los puntos; no se ha enviado."]],
[["MCP_INVALID_ENDPOINT","MCP_NOT_CONFIGURED","MCP_CONFIGURATION_INVALID"],["Configure an HTTPS MCP server and connect it first.","请先配置 HTTPS MCP 服务器并连接。","請先設定 HTTPS MCP 伺服器並連線。","HTTPSのMCPサーバーを設定し、接続してください。","Сначала настройте HTTPS-сервер MCP и подключитесь к нему.","Konfigurieren und verbinden Sie zuerst einen HTTPS-MCP-Server.","Configurez un serveur MCP HTTPS et connectez-vous d’abord.","Configura y conecta primero un servidor MCP HTTPS."]],
[["MCP_NOT_AUTHORIZED","MCP_MODE_NOT_ALLOWED"],["Enable this MCP tool and switch to Task mode to use it.","请启用此 MCP 工具，并切换到任务模式使用。","請啟用此 MCP 工具，並切換至任務模式使用。","このMCPツールを有効にして、タスクモードで使用してください。","Включите этот инструмент MCP и перейдите в режим задачи.","Aktivieren Sie dieses MCP-Werkzeug und wechseln Sie in den Aufgabenmodus.","Activez cet outil MCP et passez en mode Tâche.","Activa esta herramienta MCP y cambia al modo Tarea."]],
[["MCP_CATALOG_INVALID","MCP_ARGUMENTS_INVALID","MCP_RESULT_TOO_LARGE"],["The MCP catalog, arguments or result exceeded the supported format or size.","MCP 目录、参数或结果的格式或大小超出支持范围。","MCP 目錄、參數或結果的格式或大小超出支援範圍。","MCPの一覧、引数または結果が対応形式・サイズを超えています。","Каталог, аргументы или результат MCP имеют неподдерживаемый формат или размер.","MCP-Katalog, Argumente oder Ergebnis überschreiten das unterstützte Format oder die Größe.","Le catalogue, les paramètres ou le résultat MCP dépassent le format ou la taille pris en charge.","El catálogo, los argumentos o el resultado MCP superan el formato o tamaño admitido."]],
[["MCP_CONFIGURATION_CHANGED","MCP_CONNECTION_CANCELLED"],["The connection changed or was cancelled. Reconnect to continue.","连接已更改或取消，请重新连接。","連線已變更或取消，請重新連線。","接続が変更または中止されました。再接続してください。","Подключение изменено или отменено. Подключитесь снова.","Die Verbindung wurde geändert oder abgebrochen. Verbinden Sie sich erneut.","La connexion a changé ou a été annulée. Reconnectez-vous.","La conexión cambió o se canceló. Vuelve a conectar."]],
[["MCP_CONNECTION_TIMEOUT","MCP_CONNECTION_FAILED"],["MCP connection failed. Check the address, credentials and browser CORS access.","MCP 连接失败，请检查地址、凭据及浏览器跨域访问。","MCP 連線失敗，請檢查位址、憑證及瀏覽器跨來源存取。","MCPに接続できません。URL、認証情報、ブラウザーのCORS対応を確認してください。","Не удалось подключиться к MCP. Проверьте адрес, учётные данные и доступ CORS.","MCP-Verbindung fehlgeschlagen. Prüfen Sie Adresse, Zugangsdaten und CORS-Zugriff.","Échec de connexion MCP. Vérifiez l’adresse, les identifiants et l’accès CORS.","Falló la conexión MCP. Revisa la dirección, las credenciales y el acceso CORS."]],
[["MCP_REMOTE_TOOL_ERROR","MCP_CALL_UNCERTAIN"],["The external tool outcome is unknown. Check the external service before repeating it.","外部工具的结果尚不确定，请先核对外部服务，不要直接重试。","外部工具的結果尚不確定，請先核對外部服務，勿直接重試。","外部ツールの結果は不明です。再実行する前に外部サービスで確認してください。","Результат внешнего инструмента неизвестен. Проверьте сервис, прежде чем повторять вызов.","Das Ergebnis des externen Werkzeugs ist unklar. Prüfen Sie den Dienst vor einer Wiederholung.","Le résultat de l’outil externe est incertain. Vérifiez le service avant de réessayer.","El resultado de la herramienta externa es incierto. Comprueba el servicio antes de repetirla."]],
[["当前已有任务正在运行","此会话已在另一个窗口运行","flash_busy"],["A task is already running. Stop it before starting another.","已有任务正在运行，请先停止。","已有任務正在執行，請先停止。","タスクが実行中です。先に停止してください。","Задача уже выполняется. Сначала остановите её.","Eine Aufgabe läuft bereits. Bitte zuerst anhalten.","Une tâche est en cours. Arrêtez-la avant d’en lancer une autre.","Ya hay una tarea en curso. Detenla antes de iniciar otra."]],
[["达到本轮运行时限，进度已保存","达到本轮工具预算"],["This run reached its limit. Progress has been saved.","本轮已达到运行限制，进度已保存。","本輪已達執行限制，進度已儲存。","実行上限に達しました。進捗は保存されています。","Достигнут лимит запуска. Прогресс сохранён.","Das Ausführungslimit wurde erreicht. Der Fortschritt wurde gespeichert.","La limite d’exécution est atteinte. La progression est enregistrée.","Se alcanzó el límite de ejecución. Se ha guardado el progreso."]],
[["请先在网页主动开始屏幕共享","请先主动开始屏幕共享"],["Start screen sharing on this page first.","请先在此页面启动屏幕共享。","請先在此頁面啟動螢幕共享。","このページで画面共有を開始してください。","Сначала включите демонстрацию экрана на этой странице.","Starten Sie zuerst die Bildschirmfreigabe auf dieser Seite.","Démarrez d’abord le partage d’écran sur cette page.","Primero inicia la pantalla compartida en esta página."]],
[["此浏览器没有屏幕共享能力；请使用支持的 Safari","缺少本项目已验证后台路径所需的媒体录制能力","此浏览器没有已验证的单帧读取路径"],["This browser does not support the required screen capture features. Use a supported version of Safari.","此浏览器缺少所需的取屏能力，请使用受支持的 Safari 版本。","此瀏覽器缺少所需的擷取畫面功能，請使用支援的 Safari 版本。","必要な画面キャプチャ機能がありません。対応するSafariをご利用ください。","В браузере нет необходимых функций захвата экрана. Используйте поддерживаемую версию Safari.","Dieser Browser unterstützt die benötigte Bildschirmaufnahme nicht. Verwenden Sie eine unterstützte Safari-Version.","Ce navigateur ne dispose pas des fonctions de capture requises. Utilisez une version compatible de Safari.","Este navegador no admite las funciones de captura necesarias. Usa una versión compatible de Safari."]],
[["截图缺少图像","截图没有可保存的图像"],["The capture contains no image to save.","截图没有可保存的图像。","擷取結果沒有可儲存的影像。","保存できる画像がありません。","В снимке нет изображения для сохранения.","Die Aufnahme enthält kein speicherbares Bild.","La capture ne contient aucune image à enregistrer.","La captura no contiene ninguna imagen que se pueda guardar."]],
[["本轮截图超过24张","本轮截图超过容量预算","单张截图过大","消息图片过多","压缩后图片仍然过大"],["The image limit was reached. Reduce the number or size of captures.","图片超过限制，请减少截图数量或降低图片大小。","影像超過限制，請減少擷取次數或降低影像大小。","画像の上限に達しました。枚数またはサイズを減らしてください。","Превышен лимит изображений. Уменьшите их количество или размер.","Das Bildlimit wurde erreicht. Verringern Sie Anzahl oder Größe der Aufnahmen.","La limite d’images est atteinte. Réduisez leur nombre ou leur taille.","Se alcanzó el límite de imágenes. Reduce su número o tamaño."]],
[["截图格式或大小不受支持","图片必须为本地数据格式"],["The image format or size is not supported.","图片格式或大小不受支持。","不支援此影像格式或大小。","この画像の形式またはサイズには対応していません。","Формат или размер изображения не поддерживается.","Bildformat oder Bildgröße wird nicht unterstützt.","Le format ou la taille de l’image n’est pas pris en charge.","El formato o tamaño de imagen no es compatible."]],
[["图片设置需为320–4096像素、0.2–0.95质量"],["Choose 320–4096 pixels and image quality from 0.2 to 0.95.","请选择320–4096像素、0.2–0.95的图片质量。","請選擇320–4096像素、0.2–0.95的影像品質。","320～4096ピクセル、画質0.2～0.95を指定してください。","Укажите 320–4096 пикселей и качество от 0,2 до 0,95.","Wählen Sie 320–4096 Pixel und eine Bildqualität von 0,2 bis 0,95.","Choisissez entre 320 et 4096 pixels et une qualité de 0,2 à 0,95.","Elige entre 320 y 4096 píxeles y una calidad de 0,2 a 0,95."]],
[["多帧需要正的请求间隔"],["The interval between frames must be greater than zero.","多帧截图的间隔必须大于零。","連續擷取影像的間隔必須大於零。","連続フレームの間隔は0より大きくしてください。","Интервал между кадрами должен быть больше нуля.","Der Abstand zwischen Bildern muss größer als null sein.","L’intervalle entre les images doit être supérieur à zéro.","El intervalo entre imágenes debe ser mayor que cero."]],
[["任务内容为空或过长","搜索词为空或过长"],["Enter text within the supported length.","请输入内容，并确保长度在限制以内。","請輸入內容，並確保長度在限制以內。","上限以内の長さでテキストを入力してください。","Введите текст допустимой длины.","Geben Sie Text innerhalb der zulässigen Länge ein.","Saisissez un texte dont la longueur respecte la limite.","Introduce un texto que no supere la longitud permitida."]],
[["对话不存在","Context session does not exist"],["This conversation could not be found.","找不到此对话。","找不到此對話。","この会話が見つかりません。","Этот чат не найден.","Diese Unterhaltung wurde nicht gefunden.","Cette conversation est introuvable.","No se ha encontrado esta conversación."]],
[["未知运行模式","未知模式","模式提示词缺失"],["This conversation mode is not supported.","不支持此对话模式。","不支援此對話模式。","この会話モードには対応していません。","Этот режим чата не поддерживается.","Dieser Unterhaltungsmodus wird nicht unterstützt.","Ce mode de conversation n’est pas pris en charge.","Este modo de conversación no es compatible."]],
[["该模式不允许此工具","终止节点之后的工具未执行","该 MCP 工具尚未被用户启用"],["This tool is not available for the current task or permissions.","当前任务或权限不允许使用此工具。","目前的任務或權限不允許使用此工具。","現在のタスクまたは権限では、このツールを使用できません。","Инструмент недоступен для текущей задачи или разрешений.","Dieses Werkzeug ist mit der aktuellen Aufgabe oder Berechtigung nicht verfügbar.","Cet outil n’est pas disponible pour cette tâche ou avec ces autorisations.","Esta herramienta no está disponible para la tarea o los permisos actuales."]],
[["重复工具调用ID，不重复执行"],["A duplicate operation was skipped. Inspect the current state before retrying.","已跳过重复操作，请先检查当前状态再重试。","已略過重複操作，請先檢查目前狀態再重試。","重複する操作をスキップしました。状態を確認してから再試行してください。","Повторная операция пропущена. Перед повтором проверьте текущее состояние.","Ein doppelter Vorgang wurde übersprungen. Prüfen Sie vor einem erneuten Versuch den Zustand.","Une opération en double a été ignorée. Vérifiez l’état actuel avant de réessayer.","Se omitió una operación duplicada. Comprueba el estado antes de reintentarlo."]],
[["完成报告缺少本轮真实观察证据"],["Completion needs a screen observation from this run.","需要本轮的真实取屏证据才能确认完成。","需要本輪的實際擷取畫面，才能確認完成。","完了の確認には、今回取得した画面が必要です。","Для подтверждения завершения нужен снимок экрана из текущего запуска.","Zum Bestätigen des Abschlusses ist eine Bildschirmaufnahme aus diesem Durchlauf erforderlich.","Une observation de l’écran pendant cette exécution est nécessaire pour confirmer la fin.","Para confirmar la finalización se necesita una captura de esta ejecución."]],
[["计划属于另一条会话","运行所有权已失效"],["The task no longer belongs to this conversation. Reconnect before continuing.","此任务的会话归属已失效，请重新连接后继续。","此任務的對話歸屬已失效，請重新連線後繼續。","タスクの会話への割り当てが無効になりました。接続し直してください。","Привязка задачи к чату недействительна. Подключитесь заново.","Die Zuordnung der Aufgabe zur Unterhaltung ist nicht mehr gültig. Verbinden Sie sich erneut.","Le rattachement de la tâche à cette conversation n’est plus valide. Reconnectez-vous.","La tarea ya no está vinculada a esta conversación. Vuelve a conectarte."]],
[["请先停止此会话任务"],["Stop the task in this conversation first.","请先停止此对话中的任务。","請先停止此對話中的任務。","先にこの会話のタスクを停止してください。","Сначала остановите задачу в этом чате.","Halten Sie zuerst die Aufgabe in dieser Unterhaltung an.","Arrêtez d’abord la tâche dans cette conversation.","Primero detén la tarea de esta conversación."]],
[["此浏览器不能使用本地数据库","本地写入被中止"],["Local storage is unavailable or the write was interrupted. Check browser storage settings.","本地存储不可用或写入中断，请检查浏览器存储设置。","本機儲存空間無法使用或寫入中斷，請檢查瀏覽器儲存設定。","ローカル保存が利用できないか、中断されました。ブラウザの保存設定を確認してください。","Локальное хранилище недоступно или запись прервана. Проверьте настройки браузера.","Der lokale Speicher ist nicht verfügbar oder das Speichern wurde unterbrochen. Prüfen Sie die Browsereinstellungen.","Le stockage local est indisponible ou l’écriture a été interrompue. Vérifiez les réglages du navigateur.","El almacenamiento local no está disponible o se interrumpió la escritura. Revisa los ajustes del navegador."]],
[["请关闭此网站的旧版窗口后重试"],["Close older tabs for this site, then try again.","请关闭此网站的旧版标签页后重试。","請關閉此網站的舊版分頁後重試。","このサイトの古いタブを閉じてから再試行してください。","Закройте старые вкладки этого сайта и повторите попытку.","Schließen Sie ältere Tabs dieser Website und versuchen Sie es erneut.","Fermez les anciens onglets de ce site, puis réessayez.","Cierra las pestañas antiguas de este sitio y vuelve a intentarlo."]],
[["不支持的对话文件","无效消息","未知消息角色"],["This conversation file contains unsupported or invalid data.","此对话文件包含不受支持或无效的数据。","此對話檔案包含不支援或無效的資料。","会話ファイルに未対応または無効なデータがあります。","Файл чата содержит неподдерживаемые или недопустимые данные.","Die Unterhaltungsdatei enthält ungültige oder nicht unterstützte Daten.","Ce fichier de conversation contient des données non prises en charge ou invalides.","El archivo de conversación contiene datos no válidos o incompatibles."]],
[["请先在设置中添加并选择模型后端","请先配置后端地址和模型","缺少后端标识"],["Add an AI account in Settings and choose a model.","请先在设置中添加 AI 账号并选择模型。","請先在設定中新增 AI 帳號並選擇模型。","設定でAIアカウントを追加し、モデルを選択してください。","Добавьте аккаунт ИИ в настройках и выберите модель.","Fügen Sie in den Einstellungen ein KI-Konto hinzu und wählen Sie ein Modell.","Ajoutez un compte IA dans les réglages et choisissez un modèle.","Añade una cuenta de IA en Ajustes y elige un modelo."]],
[["请选择此账号的模型","请选择订阅模型"],["Choose a model for this account.","请选择此账号的模型。","請選擇此帳號的模型。","このアカウントのモデルを選択してください。","Выберите модель для этого аккаунта.","Wählen Sie ein Modell für dieses Konto.","Choisissez un modèle pour ce compte.","Elige un modelo para esta cuenta."]],
[["请勿将凭据写入 URL"],["Keep credentials out of URLs. Use the account credential field.","请勿把凭据写入 URL，请使用账号的凭据栏。","請勿將憑證寫入 URL，請使用帳號的憑證欄位。","URLに認証情報を含めず、アカウントの認証欄を使ってください。","Не указывайте учётные данные в URL. Используйте поле данных аккаунта.","Tragen Sie Zugangsdaten nicht in URLs ein. Verwenden Sie das Zugangsdatenfeld.","Ne placez pas d’identifiants dans l’URL. Utilisez le champ prévu pour le compte.","No incluyas credenciales en las URL. Usa el campo de credenciales de la cuenta."]],
[["后端需要 HTTPS，局域网 HTTP 受浏览器策略限制","模型后端需要 HTTPS；局域网 HTTP 受浏览器策略限制","MCP 需要浏览器可访问的 HTTPS 端点","Skill 来源需要 HTTPS"],["Use an HTTPS address that this browser can access.","请使用此浏览器可访问的 HTTPS 地址。","請使用此瀏覽器可存取的 HTTPS 位址。","ブラウザからアクセスできるHTTPSアドレスを使用してください。","Используйте HTTPS-адрес, доступный этому браузеру.","Verwenden Sie eine HTTPS-Adresse, die dieser Browser erreichen kann.","Utilisez une adresse HTTPS accessible depuis ce navigateur.","Usa una dirección HTTPS accesible desde este navegador."]],
[["不支持的模型目录协议","不支持的后端协议"],["This AI interface is not supported. Choose OpenAI, Anthropic or Codex.","不支持此 AI 接口，请选择 OpenAI、Anthropic 或 Codex。","不支援此 AI 介面，請選擇 OpenAI、Anthropic 或 Codex。","未対応のAIインターフェースです。OpenAI、Anthropic、Codexから選択してください。","Этот интерфейс ИИ не поддерживается. Выберите OpenAI, Anthropic или Codex.","Diese KI-Schnittstelle wird nicht unterstützt. Wählen Sie OpenAI, Anthropic oder Codex.","Cette interface IA n’est pas prise en charge. Choisissez OpenAI, Anthropic ou Codex.","Esta interfaz de IA no es compatible. Elige OpenAI, Anthropic o Codex."]],
[["模型目录没有返回有效列表","模型目录格式无效","模型目录分页不完整","模型目录超过限额"],["The model list could not be loaded completely. Check the account and endpoint, or enter a model ID.","未能完整获取模型列表，请检查账号和接口地址，或手动填写模型 ID。","未能完整取得模型清單，請檢查帳號及介面位址，或手動填寫模型 ID。","モデル一覧を取得できませんでした。アカウントと接続先を確認するか、モデルIDを入力してください。","Не удалось загрузить полный список моделей. Проверьте аккаунт и адрес или введите ID модели.","Die Modellliste konnte nicht vollständig geladen werden. Prüfen Sie Konto und Endpunkt oder geben Sie eine Modell-ID ein.","La liste des modèles n’a pas pu être chargée entièrement. Vérifiez le compte et l’adresse, ou saisissez un identifiant de modèle.","No se pudo cargar la lista completa de modelos. Revisa la cuenta y el servidor o introduce un ID de modelo."]],
[["模型请求超过总时限","订阅模型请求超时"],["The model request timed out. Your saved conversation is still available.","模型请求超时，已保存的对话仍然保留。","模型請求逾時，已儲存的對話仍然保留。","モデルへのリクエストがタイムアウトしました。保存済みの会話は残っています。","Время ожидания модели истекло. Сохранённый чат доступен.","Die Modellanfrage hat das Zeitlimit überschritten. Die gespeicherte Unterhaltung bleibt erhalten.","Le délai de la requête au modèle est dépassé. La conversation enregistrée reste disponible.","La solicitud al modelo agotó el tiempo de espera. La conversación guardada sigue disponible."]],
[["PROVIDER_RESPONSE_LIMIT","流式事件超过容量限制","模型输出超过容量限制","单次模型工具调用过多","工具参数过大"],["The model response exceeded a limit. No further actions were started.","模型回复超过限制，未启动后续操作。","模型回覆超過限制，未啟動後續操作。","モデルの応答が上限を超えたため、後続操作を開始していません。","Ответ модели превысил лимит. Дальнейшие действия не запущены.","Die Modellantwort hat ein Limit überschritten. Weitere Aktionen wurden nicht gestartet.","La réponse du modèle a dépassé une limite. Aucune autre action n’a été lancée.","La respuesta del modelo superó un límite. No se iniciaron más acciones."]],
[["流在完整事件结束前断开","模型响应未正常结束；未执行其中的操作","模型回复被截断；未执行其中的操作","订阅响应流被截断","订阅响应未成功完成；未执行操作","订阅响应缺少 completed 事件；未执行操作","订阅响应结束状态非 completed"],["The model response ended unexpectedly. Its actions were not executed.","模型响应异常结束，其中的操作未执行。","模型回應異常結束，其中的操作未執行。","モデルの応答が正常に完了しませんでした。含まれる操作は実行していません。","Ответ модели завершился некорректно. Действия из него не выполнялись.","Die Modellantwort wurde unerwartet beendet. Darin enthaltene Aktionen wurden nicht ausgeführt.","La réponse du modèle s’est interrompue. Les actions qu’elle contenait n’ont pas été exécutées.","La respuesta del modelo terminó de forma inesperada. Sus acciones no se ejecutaron."]],
[["PROVIDER_RESPONSE_INVALID","模型回复格式无效","模型工具调用不完整或重复","工具参数缺少起始事件","模型缺少结束状态","不完整的工具调用","订阅响应事件格式无效","工具调用结束状态缺失","工具调用身份无效或重复","工具参数 JSON 不完整","工具参数必须是对象","工具结果缺少调用 ID"],["The AI service returned an invalid response or tool call.","AI 服务返回了无效的回复或工具调用。","AI 服務傳回了無效的回覆或工具呼叫。","AIサービスから無効な応答またはツール呼び出しが返されました。","Сервис ИИ вернул некорректный ответ или вызов инструмента.","Der KI-Dienst hat eine ungültige Antwort oder einen ungültigen Werkzeugaufruf geliefert.","Le service IA a renvoyé une réponse ou un appel d’outil invalide.","El servicio de IA devolvió una respuesta o llamada a herramienta no válida."]],
[["后端没有返回候选回复","后端没有返回可读的响应流","后端返回流式错误","订阅后端未返回响应流","订阅响应为空；未执行操作"],["The AI service did not return a usable response. No actions were executed.","AI 服务没有返回可用的回复，未执行操作。","AI 服務未傳回可用的回覆，未執行操作。","AIサービスから利用可能な応答がありませんでした。操作は実行していません。","Сервис ИИ не вернул пригодный ответ. Действия не выполнялись.","Der KI-Dienst hat keine verwertbare Antwort geliefert. Es wurden keine Aktionen ausgeführt.","Le service IA n’a pas renvoyé de réponse exploitable. Aucune action n’a été exécutée.","El servicio de IA no devolvió una respuesta utilizable. No se ejecutaron acciones."]],
[["订阅响应被拒绝；未执行操作"],["The AI service declined the request. No actions were executed.","AI 服务拒绝了请求，未执行操作。","AI 服務拒絕了請求，未執行操作。","AIサービスがリクエストを拒否しました。操作は実行していません。","Сервис ИИ отклонил запрос. Действия не выполнялись.","Der KI-Dienst hat die Anfrage abgelehnt. Es wurden keine Aktionen ausgeführt.","Le service IA a refusé la requête. Aucune action n’a été exécutée.","El servicio de IA rechazó la solicitud. No se ejecutaron acciones."]],
[["模型通信失败，敏感错误已隐藏"],["The AI connection failed. Sensitive error details have been hidden.","AI 连接失败，敏感错误信息已隐藏。","AI 連線失敗，敏感錯誤資訊已隱藏。","AIへの接続に失敗しました。機密情報を含む詳細は非表示にしています。","Ошибка соединения с ИИ. Конфиденциальные детали скрыты.","Die KI-Verbindung ist fehlgeschlagen. Vertrauliche Fehlerdetails wurden ausgeblendet.","La connexion à l’IA a échoué. Les détails sensibles ont été masqués.","Falló la conexión con la IA. Se han ocultado los detalles confidenciales."]],
[["尚未登录","订阅账号尚未登录","请先选择已登录的订阅账号","请选择已登录的订阅账号"],["Sign in and choose a subscription account first.","请先登录并选择订阅账号。","請先登入並選擇訂閱帳號。","先にログインして、サブスクリプションのアカウントを選択してください。","Сначала войдите и выберите аккаунт с подпиской.","Melden Sie sich zuerst an und wählen Sie ein Abonnementkonto.","Connectez-vous et choisissez d’abord un compte abonné.","Primero inicia sesión y elige una cuenta con suscripción."]],
[["登录已到期，请重新登录","订阅登录已到期，请重新登录"],["Your sign-in has expired. Sign in again.","登录已到期，请重新登录。","登入已到期，請重新登入。","ログインの有効期限が切れました。再度ログインしてください。","Срок входа истёк. Войдите снова.","Ihre Anmeldung ist abgelaufen. Melden Sie sich erneut an.","Votre connexion a expiré. Reconnectez-vous.","Tu sesión ha caducado. Vuelve a iniciar sesión."]],
[["订阅账号不存在","账号已替换或移除","刷新期间账号已移除","请求前账号已更换"],["This account has been removed or changed. Select the account again.","此账号已被移除或更改，请重新选择。","此帳號已被移除或變更，請重新選擇。","アカウントが削除または変更されました。選択し直してください。","Аккаунт удалён или изменён. Выберите его заново.","Dieses Konto wurde entfernt oder geändert. Wählen Sie es erneut aus.","Ce compte a été supprimé ou modifié. Sélectionnez-le à nouveau.","Esta cuenta se eliminó o cambió. Vuelve a seleccionarla."]],
[["设备码已超时","登录尝试已超时","设备码已超时或兑换字段不完整"],["The sign-in code has expired. Start sign-in again.","登录码已到期，请重新发起登录。","登入碼已到期，請重新開始登入。","ログインコードの有効期限が切れました。ログインをやり直してください。","Срок действия кода истёк. Начните вход заново.","Der Anmeldecode ist abgelaufen. Starten Sie die Anmeldung erneut.","Le code de connexion a expiré. Recommencez la connexion.","El código de inicio de sesión ha caducado. Inicia el proceso de nuevo."]],
[["用户未授权本次登录","设备码验证失败"],["Sign-in was not authorized. Try again when ready.","本次登录未获授权，准备好后可重试。","此次登入未獲授權，準備好後可重試。","ログインが承認されませんでした。準備ができたら再試行してください。","Вход не был разрешён. Повторите попытку, когда будете готовы.","Die Anmeldung wurde nicht genehmigt. Versuchen Sie es erneut, wenn Sie bereit sind.","La connexion n’a pas été autorisée. Réessayez lorsque vous êtes prêt.","No se autorizó el inicio de sesión. Vuelve a intentarlo cuando quieras."]],
[["需要解锁口令"],["Enter your local vault passphrase.","请输入本地凭据库的解锁口令。","請輸入本機憑證庫的解鎖密語。","ローカル保管庫のパスフレーズを入力してください。","Введите парольную фразу локального хранилища.","Geben Sie die Passphrase für Ihren lokalen Tresor ein.","Saisissez la phrase secrète du coffre local.","Introduce la frase de contraseña de tu almacén local."]],
[["不支持的凭据格式","缺少访问令牌","登录结果缺少访问令牌","设备码兑换结果不完整","设备码响应不完整","令牌到期时间无效","登录回调缺少 code"],["The sign-in response is incomplete or invalid. Start sign-in again.","登录响应不完整或无效，请重新登录。","登入回應不完整或無效，請重新登入。","ログイン応答が不完全または無効です。ログインをやり直してください。","Ответ при входе неполный или некорректный. Войдите заново.","Die Anmeldeantwort ist unvollständig oder ungültig. Melden Sie sich erneut an.","La réponse de connexion est incomplète ou invalide. Recommencez la connexion.","La respuesta de inicio de sesión está incompleta o no es válida. Inicia sesión de nuevo."]],
[["账号身份与令牌不匹配","重新登录身份与选中账号不匹配","刷新返回了不匹配的账号","登录身份签名或账号验证失败","登录回调地址或 state 不匹配","回调客户端与选中账号不匹配"],["The returned identity does not match this sign-in. No credentials were accepted.","返回的身份与本次登录不匹配，未接收凭据。","傳回的身分與此次登入不符，未接受憑證。","返されたIDが今回のログインと一致しないため、認証情報を受け入れていません。","Полученная личность не соответствует запросу входа. Данные не приняты.","Die zurückgegebene Identität passt nicht zu dieser Anmeldung. Zugangsdaten wurden nicht übernommen.","L’identité reçue ne correspond pas à cette connexion. Aucun identifiant n’a été accepté.","La identidad recibida no coincide con este inicio de sesión. No se aceptaron credenciales."]],
[["订阅账号缺少 plan 使用授权","尚未验证身份或获得 ChatGPT plan 使用授权","刷新后缺少 plan 使用授权"],["This account has not granted the required ChatGPT plan authorization. Sign in with the supported flow.","此账号尚未授予所需的 ChatGPT 订阅权限，请使用支持的流程登录。","此帳號尚未授予所需的 ChatGPT 訂閱權限，請使用支援的流程登入。","必要なChatGPTプランの権限がありません。対応する方法でログインしてください。","Аккаунт не предоставил нужное разрешение ChatGPT. Используйте поддерживаемый способ входа.","Diesem Konto fehlt die erforderliche ChatGPT-Abonnementberechtigung. Nutzen Sie den unterstützten Anmeldeablauf.","Ce compte n’a pas accordé l’autorisation ChatGPT requise. Utilisez une méthode de connexion compatible.","Esta cuenta no ha concedido la autorización de ChatGPT necesaria. Usa un método de inicio de sesión compatible."]],
[["订阅连接失败；请检查浏览器 CORS、网络或服务可用性"],["Could not connect to the subscription service. Check the network and browser access restrictions.","无法连接订阅服务，请检查网络和浏览器的访问限制。","無法連接訂閱服務，請檢查網路及瀏覽器的存取限制。","サブスクリプションサービスに接続できません。ネットワークとブラウザのアクセス制限を確認してください。","Не удалось подключиться к сервису подписки. Проверьте сеть и ограничения браузера.","Der Abonnementdienst ist nicht erreichbar. Prüfen Sie Netzwerk und Zugriffsbeschränkungen des Browsers.","Impossible de joindre le service d’abonnement. Vérifiez le réseau et les restrictions du navigateur.","No se pudo conectar con el servicio de suscripción. Revisa la red y las restricciones del navegador."]],
[["设备码登录尚未配置可验证的 OAuth 客户端","需要已签发的账号客户端 ID","缺少签发的客户端 ID","需要独立的账号登记 ID","不同账号请使用独立登记 ID","请为不同客户端登记创建独立账号 ID","需要稳定的 hostId","未知订阅登录方式","动态注册需要 authorization-code 流程","注册客户端请使用经过 ID 签名验证的 authorization-code 流程","官方 SIWC 要求 127.0.0.1 /auth/callback 回调","Codex 令牌缺少 ChatGPT account ID","订阅凭据仅允许发送到官方 HTTPS 地址","登录尝试无效或已使用"],["The subscription sign-in configuration is invalid for this flow. Use a supported account setup.","订阅登录配置不适用于此流程，请使用受支持的账号配置。","訂閱登入設定不適用於此流程，請使用支援的帳號設定。","この方式に必要なログイン設定が正しくありません。対応するアカウント設定をご利用ください。","Настройки подписки не подходят для этого способа входа. Используйте поддерживаемую конфигурацию.","Die Abonnementanmeldung ist für diesen Ablauf nicht korrekt eingerichtet. Nutzen Sie eine unterstützte Kontokonfiguration.","La configuration de connexion à l’abonnement ne convient pas à cette méthode. Utilisez une configuration compatible.","La configuración de acceso a la suscripción no es válida para este método. Usa una configuración compatible."]],
[["Skill JSON 格式无效","Skill 缺少标识","无效 Skill 或资源路径","Skill 文件路径或类型不支持","重复 Skill 文件","Skill 缺少入口正文","INVALID_PAYLOAD","INVALID_PATH","INVALID_SKILL_ID"],["The Skill package has an invalid name, path or file structure.","技能包的标识、路径或文件结构无效。","技能套件的識別碼、路徑或檔案結構無效。","スキルパッケージの名前、パス、または構成が無効です。","Недопустимое имя, путь или структура пакета навыка.","Name, Pfad oder Dateistruktur des Skill-Pakets ist ungültig.","Le nom, le chemin ou la structure du paquet de compétence est invalide.","El nombre, la ruta o la estructura del paquete de habilidad no es válido."]],
[["Skill 未安装或未启用","Skill 资源不存在或为空"],["This Skill or reference is not installed, enabled or available.","此技能或参考资源未安装、未启用或不存在。","此技能或參考資源未安裝、未啟用或不存在。","このスキルまたは資料が未インストール、無効、または利用不可です。","Навык или материал не установлен, не включён или недоступен.","Dieser Skill oder Verweis ist nicht installiert, aktiviert oder verfügbar.","Cette compétence ou cette ressource n’est pas installée, activée ou disponible.","Esta habilidad o referencia no está instalada, activada o disponible."]],
[["Skill 文件过大","Skill 包过大","Skill 正文超过当前上下文限额","PACKAGE_TOO_LARGE"],["The Skill package is too large. Reduce its instructions or resources.","技能包过大，请精简说明或参考资源。","技能套件過大，請精簡說明或參考資源。","スキルパッケージが大きすぎます。説明または資料を減らしてください。","Пакет навыка слишком большой. Сократите инструкции или материалы.","Das Skill-Paket ist zu groß. Kürzen Sie Anweisungen oder Ressourcen.","Le paquet de compétence est trop volumineux. Réduisez les instructions ou les ressources.","El paquete de habilidad es demasiado grande. Reduce las instrucciones o los recursos."]],
[["Skill 清单不匹配","Skill 内容校验失败"],["The Skill package failed its integrity check. It has not been installed.","技能包未通过完整性校验，未安装。","技能套件未通過完整性檢查，未安裝。","スキルの整合性確認に失敗しました。インストールしていません。","Пакет навыка не прошёл проверку целостности и не установлен.","Die Integritätsprüfung des Skill-Pakets ist fehlgeschlagen. Es wurde nicht installiert.","Le contrôle d’intégrité du paquet de compétence a échoué. Il n’a pas été installé.","Falló la comprobación de integridad del paquete de habilidad. No se ha instalado."]],
[["SKILL_READ_ONLY","SKILL_NOT_OWNED"],["Community and built-in Skills are read-only. You can edit and publish only your own Skills.","社区和内置技能为只读；只能编辑和发布自己创作的技能。","社群及內建技能為唯讀；只能編輯及發佈自己創作的技能。","コミュニティと内蔵のスキルは読み取り専用です。編集・公開できるのは自分で作成したスキルのみです。","Встроенные и загруженные навыки доступны только для чтения. Редактировать и публиковать можно только собственные.","Community- und integrierte Skills sind schreibgeschützt. Nur eigene Skills können bearbeitet und veröffentlicht werden.","Les compétences intégrées et communautaires sont en lecture seule. Seules vos créations peuvent être modifiées et publiées.","Las habilidades integradas y de la comunidad son de solo lectura. Solo puedes editar y publicar tus propias creaciones."]],
[["IDENTITY_REQUIRED"],["Create or restore your creator identity before publishing.","发布前请创建或恢复创作者身份。","發佈前請建立或還原創作者身分。","公開する前に、作成者IDを作成または復元してください。","Перед публикацией создайте или восстановите личность автора.","Erstellen Sie vor dem Veröffentlichen Ihre Autorenidentität oder stellen Sie sie wieder her.","Créez ou restaurez votre identité d’auteur avant de publier.","Crea o restaura tu identidad de autor antes de publicar."]],
[["设备时钟响应无效","校时过程中设备重启，请重新连接"],["The device clock is unavailable or the device restarted. Reconnect it.","设备时钟无效或设备已重启，请重新连接。","裝置時鐘無效或裝置已重新啟動，請重新連線。","端末の時刻が取得できないか、端末が再起動しました。接続し直してください。","Часы устройства недоступны или устройство перезапустилось. Подключитесь заново.","Die Gerätezeit ist ungültig oder das Gerät wurde neu gestartet. Verbinden Sie es erneut.","L’horloge est indisponible ou l’appareil a redémarré. Reconnectez-le.","El reloj del dispositivo no está disponible o se ha reiniciado. Vuelve a conectarlo."]],
[["无效的 MCP SSE JSON","MCP 返回未匹配的请求 ID","不支持的 MCP 协议版本","无效工具目录","MCP 工具目录超过限额","MCP 工具分页超过限额","此轻量客户端不支持服务器主动请求"],["The MCP server returned an unsupported response. Check its compatibility and tool list.","MCP 服务器返回了不受支持的响应，请检查兼容性和工具列表。","MCP 伺服器傳回不支援的回應，請檢查相容性及工具清單。","MCPサーバーから未対応の応答が返されました。互換性とツール一覧を確認してください。","Сервер MCP вернул неподдерживаемый ответ. Проверьте совместимость и список инструментов.","Der MCP-Server lieferte eine nicht unterstützte Antwort. Prüfen Sie Kompatibilität und Werkzeugliste.","Le serveur MCP a renvoyé une réponse incompatible. Vérifiez sa compatibilité et la liste des outils.","El servidor MCP devolvió una respuesta incompatible. Revisa su compatibilidad y la lista de herramientas."]],
[["flash_manifest","flash_download"],["The firmware files could not be loaded. Refresh the page and try again.","无法加载固件文件，请刷新页面后重试。","無法載入韌體檔案，請重新整理頁面後重試。","ファームウェアを読み込めませんでした。ページを更新して再試行してください。","Не удалось загрузить прошивку. Обновите страницу и повторите попытку.","Die Firmwaredateien konnten nicht geladen werden. Laden Sie die Seite neu und versuchen Sie es erneut.","Les fichiers du micrologiciel n’ont pas pu être chargés. Actualisez la page et réessayez.","No se pudieron cargar los archivos de firmware. Actualiza la página y vuelve a intentarlo."]],
[["flash_integrity","flash_dependency"],["Firmware verification failed. The device has not been flashed.","固件校验失败，未烧录设备。","韌體驗證失敗，未燒錄裝置。","ファームウェアの確認に失敗しました。書き込みは行っていません。","Проверка прошивки не пройдена. Запись не выполнялась.","Die Firmwareprüfung ist fehlgeschlagen. Es wurde nichts geflasht.","La vérification du micrologiciel a échoué. Aucune écriture n’a été effectuée.","Falló la verificación del firmware. No se ha grabado el dispositivo."]],
[["flash_unsupported"],["Use Chrome or Edge on a computer with USB serial support.","请在电脑上使用支持 USB 串口的 Chrome 或 Edge。","請在電腦上使用支援 USB 序列埠的 Chrome 或 Edge。","USBシリアル対応のパソコンでChromeまたはEdgeを使用してください。","Используйте Chrome или Edge на компьютере с поддержкой USB-последовательного порта.","Verwenden Sie Chrome oder Edge auf einem Computer mit USB-Serial-Unterstützung.","Utilisez Chrome ou Edge sur un ordinateur prenant en charge les ports série USB.","Usa Chrome o Edge en un ordenador compatible con puertos serie USB."]],
[["flash_capacity_c2"],["This ESP32-C2 firmware needs at least 2 MB of flash.","此 ESP32-C2 固件需要至少 2 MB 闪存。","此 ESP32-C2 韌體需要至少 2 MB 快閃記憶體。","この ESP32-C2 ファームウェアには 2 MB 以上のフラッシュが必要です。","Для этой прошивки ESP32-C2 требуется не менее 2 МБ флеш-памяти.","Diese ESP32-C2-Firmware benötigt mindestens 2 MB Flash-Speicher.","Ce firmware ESP32-C2 nécessite au moins 2 Mo de mémoire flash.","Este firmware ESP32-C2 necesita al menos 2 MB de memoria flash."]],
[["flash_crystal"],["The ESP32-C2 crystal could not be matched with available firmware. Refresh the installer and try again.","未能匹配 ESP32-C2 晶振对应的固件，请刷新烧录页面后重试。","無法匹配 ESP32-C2 晶振對應的韌體，請重新整理燒錄頁面後再試。","ESP32-C2 の水晶周波数に合うファームウェアがありません。インストーラーを再読み込みしてください。","Не удалось подобрать прошивку для частоты кварца ESP32-C2. Обновите страницу установки.","Keine passende Firmware für den Quarz des ESP32-C2 gefunden. Bitte die Installationsseite neu laden.","Aucun firmware ne correspond au quartz de l’ESP32-C2. Actualisez la page d’installation.","No se encontró firmware para el cristal del ESP32-C2. Recarga el instalador."]],
[["flash_chip_mismatch"],["The selected firmware does not match this chip. Choose the correct board.","所选固件与芯片不匹配，请选择正确的开发板。","所選韌體與晶片不符，請選擇正確的開發板。","選択したファームウェアとチップが一致しません。正しいボードを選んでください。","Выбранная прошивка не соответствует чипу. Выберите правильную плату.","Die gewählte Firmware passt nicht zum Chip. Wählen Sie das richtige Board.","Le micrologiciel choisi ne correspond pas à la puce. Choisissez la bonne carte.","El firmware elegido no corresponde al chip. Selecciona la placa correcta."]],
[["flash_capacity"],["This firmware requires at least 4 MB of flash storage.","此固件至少需要4 MB闪存。","此韌體至少需要4 MB快閃記憶體。","このファームウェアには4 MB以上のフラッシュメモリが必要です。","Для этой прошивки требуется не менее 4 МБ флеш-памяти.","Diese Firmware benötigt mindestens 4 MB Flash-Speicher.","Ce micrologiciel nécessite au moins 4 Mo de mémoire flash.","Este firmware necesita al menos 4 MB de memoria flash."]],
[["无法解锁，请检查口令与账号类型。","CREDENTIAL_UNLOCK_FAILED"],["Unable to unlock. Check the passphrase and account type.","无法解锁，请检查口令与账号类型。","無法解鎖，請檢查密語與帳號類型。","解除できません。パスフレーズとアカウントの種類を確認してください。","Не удалось разблокировать. Проверьте парольную фразу и тип аккаунта.","Entsperren nicht möglich. Prüfen Sie Passphrase und Kontotyp.","Déverrouillage impossible. Vérifiez la phrase secrète et le type de compte.","No se pudo desbloquear. Revisa la contraseña y el tipo de cuenta."]],
[["CAPTURE_SOURCE_CHANGED"],["Screen sharing stopped or its source changed. The old frame was discarded. Start sharing again.","屏幕共享已停止或来源已变化，旧帧已丢弃。请重新开始共享。","螢幕共享已停止或來源已變更，舊畫面已捨棄。請重新開始共享。","画面共有が停止したか、共有元が変わりました。古いフレームは破棄しました。共有を開始し直してください。","Показ экрана остановлен или источник изменился. Старый кадр отброшен. Начните показ заново.","Die Bildschirmfreigabe wurde beendet oder ihre Quelle geändert. Das alte Bild wurde verworfen. Starten Sie die Freigabe erneut.","Le partage d’écran s’est arrêté ou sa source a changé. L’ancienne image a été écartée. Relancez le partage.","La pantalla compartida se detuvo o cambió de origen. Se descartó la imagen anterior. Inicia la pantalla compartida de nuevo."]],
[["达到本轮步骤预算，进度已保存；尚未确认任务完成。"],["Run limit reached. Progress was saved; completion has not been verified.","达到本轮步骤预算，进度已保存；尚未确认任务完成。","已達本輪步驟上限，進度已儲存；尚未確認任務完成。","今回のステップ上限に達しました。進捗は保存されていますが、完了は未確認です。","Достигнут лимит шагов. Прогресс сохранён, завершение ещё не подтверждено.","Das Schrittlimit wurde erreicht. Der Fortschritt ist gespeichert; der Abschluss ist noch nicht bestätigt.","La limite d’étapes est atteinte. La progression est enregistrée ; la fin de la tâche n’a pas été vérifiée.","Se alcanzó el límite de pasos. El progreso está guardado; la finalización no se ha verificado."]],
[["任务已停止；已提交的输入不会自动撤销","用户停止了任务"],["Task stopped. Input already sent to the device is not undone.","任务已停止；已提交的输入不会自动撤销。","任務已停止；已提交的輸入不會自動復原。","タスクを停止しました。送信済みの操作は取り消されません。","Задача остановлена. Уже отправленные действия не отменяются.","Die Aufgabe wurde angehalten. Bereits gesendete Eingaben werden nicht rückgängig gemacht.","La tâche est arrêtée. Les actions déjà envoyées ne sont pas annulées.","La tarea se ha detenido. Las acciones ya enviadas no se deshacen."]],
[["操作结果尚未核对，后续步骤已停止。","相同操作连续失败，需要新证据或调整任务"],["Further actions stopped. Check the current screen and operation status before continuing.","后续操作已停止，请检查当前屏幕和操作状态后再继续。","後續操作已停止，請檢查目前畫面與操作狀態後再繼續。","後続操作を停止しました。画面と操作状態を確認してから続けてください。","Дальнейшие действия остановлены. Проверьте экран и состояние операции перед продолжением.","Weitere Aktionen wurden angehalten. Prüfen Sie Bildschirm und Vorgangsstatus, bevor Sie fortfahren.","Les actions suivantes sont arrêtées. Vérifiez l’écran et l’état de l’opération avant de continuer.","Se detuvieron las siguientes acciones. Comprueba la pantalla y el estado antes de continuar."]],
[["SKILL_EXISTS","VERSION_EXISTS","STALE_REVISION","REPLAY_OR_CONFLICT","SKILL_CONFLICT"],["This Skill or version already exists, or a newer revision was published. Refresh before trying again.","此技能或版本已存在，或已有新修订发布；请刷新后再试。","此技能或版本已存在，或已有新修訂發佈；請重新整理後再試。","スキルまたはバージョンが既に存在するか、新しい改訂が公開されています。更新して再試行してください。","Навык или версия уже существует либо опубликована новая редакция. Обновите данные и повторите попытку.","Dieser Skill oder diese Version existiert bereits, oder eine neue Revision wurde veröffentlicht. Aktualisieren Sie vor einem erneuten Versuch.","Cette compétence ou cette version existe déjà, ou une nouvelle révision a été publiée. Actualisez avant de réessayer.","Esta habilidad o versión ya existe o se ha publicado una revisión más reciente. Actualiza antes de reintentarlo."]],
[["SKILL_NOT_FOUND"],["This Skill was not found. Refresh the catalog.","找不到此技能，请刷新目录。","找不到此技能，請重新整理目錄。","スキルが見つかりません。一覧を更新してください。","Навык не найден. Обновите каталог.","Dieser Skill wurde nicht gefunden. Aktualisieren Sie den Katalog.","Cette compétence est introuvable. Actualisez le catalogue.","No se ha encontrado esta habilidad. Actualiza el catálogo."]],
[["IDENTITY_STORAGE_UNAVAILABLE"],["Your creator identity could not be saved in this browser. Check local storage permissions.","无法在此浏览器保存创作者身份，请检查本地存储权限。","無法在此瀏覽器儲存創作者身分，請檢查本機儲存權限。","このブラウザに作成者IDを保存できません。ローカル保存の権限を確認してください。","Не удалось сохранить личность автора в браузере. Проверьте разрешения хранилища.","Ihre Autorenidentität konnte nicht im Browser gespeichert werden. Prüfen Sie die Speicherberechtigungen.","Votre identité d’auteur n’a pas pu être enregistrée dans ce navigateur. Vérifiez les autorisations de stockage.","No se pudo guardar tu identidad de autor en este navegador. Revisa los permisos de almacenamiento."]],
[["IDENTITY_DECRYPT_FAILED","INVALID_IDENTITY_BACKUP"],["The identity backup could not be opened. Check the file and passphrase.","无法打开身份备份，请检查文件和解锁口令。","無法開啟身分備份，請檢查檔案及解鎖密語。","IDのバックアップを開けません。ファイルとパスフレーズを確認してください。","Не удалось открыть резервную копию личности. Проверьте файл и парольную фразу.","Die Identitätssicherung konnte nicht geöffnet werden. Prüfen Sie Datei und Passphrase.","La sauvegarde d’identité n’a pas pu être ouverte. Vérifiez le fichier et la phrase secrète.","No se pudo abrir la copia de identidad. Revisa el archivo y la frase de contraseña."]],
[["PASSPHRASE_REQUIRED"],["Enter a passphrase to protect or unlock your identity backup.","请输入用于加密或解锁身份备份的口令。","請輸入用於加密或解鎖身分備份的密語。","IDのバックアップを保護または解除するパスフレーズを入力してください。","Введите парольную фразу для защиты или открытия копии личности.","Geben Sie eine Passphrase zum Schützen oder Entsperren der Identitätssicherung ein.","Saisissez une phrase secrète pour protéger ou ouvrir la sauvegarde d’identité.","Introduce una frase de contraseña para proteger o abrir la copia de identidad."]],
[["COMMUNITY_NOT_CONFIGURED"],["The community is unavailable. Try again later.","社区暂时无法连接，请稍后重试。","社群暫時無法連線，請稍後再試。","コミュニティに接続できません。しばらくしてから再試行してください。","Сообщество недоступно. Повторите попытку позже.","Die Community ist nicht erreichbar. Versuchen Sie es später erneut.","La communauté est indisponible. Réessayez plus tard.","La comunidad no está disponible. Inténtalo más tarde."]],
[["COMMUNITY_UNREACHABLE","COMMUNITY_BAD_RESPONSE","COMMUNITY_REQUEST_FAILED"],["The skill community is temporarily unavailable. Try again later.","技能社区暂时无法访问，请稍后重试。","技能社群暫時無法存取，請稍後再試。","スキルコミュニティは一時的に利用できません。しばらくしてから再試行してください。","Сообщество навыков временно недоступно. Повторите попытку позже.","Die Skill-Community ist vorübergehend nicht erreichbar. Bitte später erneut versuchen.","La communauté de Skills est temporairement indisponible. Réessayez plus tard.","La comunidad de habilidades no está disponible temporalmente. Inténtalo más tarde."]],
[["BAD_SIGNATURE","INVALID_IDENTITY","INVALID_PUBLICATION","AUDIENCE_MISMATCH","PUBLICATION_EXPIRED"],["The publication signature or authorization is invalid. Nothing was published.","发布签名或授权无效，未发布任何内容。","發佈簽章或授權無效，未發佈任何內容。","公開の署名または承認が無効です。何も公開していません。","Подпись или разрешение на публикацию недействительны. Ничего не опубликовано.","Die Veröffentlichungssignatur oder Berechtigung ist ungültig. Es wurde nichts veröffentlicht.","La signature ou l’autorisation de publication est invalide. Rien n’a été publié.","La firma o autorización de publicación no es válida. No se ha publicado nada."]],
[["PUBLISH_REQUIRES_USER_ACTION"],["Choose Publish yourself to share a Skill. The assistant cannot publish automatically.","共享技能需由你点击“发布”，助手不能自动发布。","共享技能需由你點選「發佈」，助理不能自動發佈。","スキルを共有するには、自分で「公開」を選んでください。アシスタントによる自動公開はできません。","Чтобы поделиться навыком, нажмите «Опубликовать». Ассистент не публикует автоматически.","Wählen Sie selbst „Veröffentlichen“, um einen Skill zu teilen. Der Assistent veröffentlicht nicht automatisch.","Choisissez vous-même Publier pour partager une compétence. L’assistant ne peut pas publier automatiquement.","Elige Publicar para compartir una habilidad. El asistente no puede publicarla automáticamente."]],
[["One complete tool/message group exceeds the summary input; increase the context limit or use a model with a larger context window","One complete tool/message group exceeds the bounded summary input; choose a larger context limit or explicit extractive strategy","Previous summary plus one complete group exceeds the bounded summary input","Compaction summary exceeded the estimated target budget","Compaction returned no valid plain-text summary"],["Context compaction failed. Try again or choose a model with a larger context window.","上下文压缩失败，请重试或换用支持更长上下文的模型。","上下文壓縮失敗，請重試或改用支援更長上下文的模型。","コンテキストを圧縮できません。再試行するか、より長いコンテキストに対応したモデルを選んでください。","Не удалось сжать контекст. Повторите попытку или выберите модель с большим окном контекста.","Der Kontext konnte nicht komprimiert werden. Versuchen Sie es erneut oder wählen Sie ein Modell mit größerem Kontextfenster.","La réduction du contexte a échoué. Réessayez ou choisissez un modèle acceptant un contexte plus long.","No se pudo reducir el contexto. Reintenta o elige un modelo con una ventana de contexto mayor."]],
[["DEVICE_HTTPS_REQUIRED","DEVICE_INVALID_URL"],["Enter the local-network address of your device.","请输入设备的局域网地址。","請輸入裝置的區域網路位址。","デバイスのローカルネットワークアドレスを入力してください。","Введите адрес устройства в локальной сети.","Gib die lokale Netzwerkadresse deines Geräts ein.","Saisissez l’adresse de votre appareil sur le réseau local.","Introduce la dirección de tu dispositivo en la red local."]],
[["DEVICE_IDENTITY_UNVERIFIED","DEVICE_IDENTITY_MISMATCH","DEVICE_CREDENTIAL_MISMATCH"],["The bridge information has changed or does not match. Get its connection information again, then reconnect.","桥信息已变化或不匹配，请重新获取连接信息后再连接。","橋接器資訊已變更或不符，請重新取得連線資訊後再連線。","ブリッジ情報が変更されたか一致しません。接続情報を再取得してから接続し直してください。","Данные моста изменились или не совпадают. Получите данные подключения заново и подключитесь снова.","Die Bridge-Daten haben sich geändert oder stimmen nicht überein. Rufe die Verbindungsdaten erneut ab und verbinde dich danach neu.","Les informations du pont ont changé ou ne correspondent pas. Récupérez à nouveau les informations de connexion, puis reconnectez-vous.","La información del puente cambió o no coincide. Obtén de nuevo los datos de conexión y vuelve a conectarte."]],
[["DEVICE_PAIRING_REQUIRED","DEVICE_AUTH_EXPIRED","DEVICE_ACCESS_DENIED"],["Reconnect the ESP32 bridge to renew this browser’s connection.","请重新连接 ESP32 桥，以更新此浏览器的连接。","請重新連接 ESP32 橋接器，以更新此瀏覽器的連線。","このブラウザの接続を更新するため、ESP32 ブリッジに再接続してください。","Подключитесь к мосту ESP32 заново, чтобы обновить подключение этого браузера.","Verbinde die ESP32-Bridge erneut, um die Verbindung dieses Browsers zu erneuern.","Reconnectez le pont ESP32 pour renouveler la connexion de ce navigateur.","Vuelve a conectar el puente ESP32 para renovar la conexión de este navegador."]],
[["DEVICE_BINDING_UNVERIFIED","DEVICE_CHALLENGE_INVALID"],["Confirm this phone using the dedicated keyboard verification field before enabling control.","启用控制前，请在专用键盘验证输入框中确认当前这台手机。","啟用控制前，請在專用鍵盤驗證輸入欄位確認目前這台手機。","操作を有効にする前に、専用のキーボード確認欄でこの端末を確認してください。","Перед включением управления подтвердите этот телефон в специальном поле проверки клавиатуры.","Bestätigen Sie dieses Telefon im vorgesehenen Tastatur-Prüffeld, bevor Sie die Steuerung aktivieren.","Confirmez ce téléphone dans le champ de vérification du clavier avant d’activer le contrôle.","Confirma este teléfono en el campo de verificación del teclado antes de activar el control."]],
[["DEVICE_TARGET_NOT_READY","DEVICE_NOT_READY"],["The Bluetooth target is not ready. Check pairing and connection, then enable AssistiveTouch for pointer input.","蓝牙目标尚未就绪。请检查配对和连接，并开启辅助触控以使用指针。","藍牙目標尚未就緒。請檢查配對與連線，並開啟輔助觸控以使用指標。","Bluetooth端末の準備ができていません。ペアリングと接続を確認し、ポインタ操作にはAssistiveTouchを有効にしてください。","Устройство Bluetooth не готово. Проверьте сопряжение и соединение; для указателя включите AssistiveTouch.","Das Bluetooth-Ziel ist noch nicht bereit. Prüfen Sie Kopplung und Verbindung und aktivieren Sie AssistiveTouch für den Zeiger.","La cible Bluetooth n’est pas prête. Vérifiez l’association et la connexion, puis activez AssistiveTouch pour le pointeur.","El dispositivo Bluetooth no está listo. Revisa el emparejamiento y la conexión y activa AssistiveTouch para el puntero."]],
[["DEVICE_WRITER_BUSY"],["Another task holds control of this phone. Stop it or wait before continuing.","另一项任务正在控制此手机，请停止该任务或等待后再继续。","另一項任務正在控制此手機，請停止該任務或稍後再繼續。","別のタスクがこの端末を操作中です。停止するか、終了を待ってください。","Другой задаче принадлежит управление телефоном. Остановите её или дождитесь завершения.","Eine andere Aufgabe steuert dieses Telefon. Halten Sie sie an oder warten Sie vor dem Fortfahren.","Une autre tâche contrôle ce téléphone. Arrêtez-la ou attendez avant de continuer.","Otra tarea controla este teléfono. Detenla o espera antes de continuar."]],
[["DEVICE_LEASE_EXPIRED","DEVICE_LEASE_ID_REUSED","DEVICE_REBOOTED","DEVICE_STATE_CHANGED"],["Control state changed or expired. Refresh the connection and observe the phone before continuing.","控制状态已变化或到期。请刷新连接并重新观察手机后再继续。","控制狀態已變更或到期。請重新整理連線並再次觀察手機後再繼續。","操作状態が変更されたか期限切れです。接続を更新し、端末の画面を確認してから続けてください。","Состояние управления изменилось или истекло. Обновите соединение и проверьте экран телефона.","Der Steuerungszustand hat sich geändert oder ist abgelaufen. Aktualisieren Sie die Verbindung und prüfen Sie das Telefon.","L’état du contrôle a changé ou a expiré. Actualisez la connexion et observez le téléphone avant de continuer.","El estado del control cambió o caducó. Actualiza la conexión y observa el teléfono antes de continuar."]],
[["DEVICE_RESULT_UNKNOWN","DEVICE_RELEASE_UNKNOWN"],["The input result is unconfirmed. Check the phone before retrying; the action will not be repeated automatically.","输入结果尚未确认。请先检查手机再重试，操作不会自动重复。","輸入結果尚未確認。請先檢查手機再重試，操作不會自動重複。","入力結果を確認できていません。再試行の前に端末を確認してください。操作は自動で繰り返しません。","Результат ввода не подтверждён. Проверьте телефон перед повтором; действие не повторяется автоматически.","Das Eingabeergebnis ist unbestätigt. Prüfen Sie das Telefon vor einem erneuten Versuch; die Aktion wird nicht automatisch wiederholt.","Le résultat de la saisie n’est pas confirmé. Vérifiez le téléphone avant de réessayer ; l’action ne sera pas répétée automatiquement.","El resultado de la entrada no está confirmado. Revisa el teléfono antes de reintentar; la acción no se repetirá automáticamente."]],
[["DEVICE_TLS_OR_NETWORK_ERROR","DEVICE_TIMEOUT"],["Could not connect to the ESP32. Check that it is powered on and connected to the network, then try again.","无法连接 ESP32。请确认设备已通电并连接网络，然后重试。","無法連接 ESP32。請確認裝置已通電並連接網路，然後再試。","ESP32に接続できません。電源とネットワーク接続を確認して再試行してください。","Не удалось подключиться к ESP32. Проверьте питание и подключение к сети.","Der ESP32 ist nicht erreichbar. Prüfen Sie Stromversorgung und Netzwerkverbindung und versuchen Sie es erneut.","Impossible de joindre l’ESP32. Vérifiez son alimentation et sa connexion réseau, puis réessayez.","No se pudo conectar al ESP32. Comprueba la alimentación y la conexión de red y reintenta."]],
[["DEVICE_REQUEST_CANCELLED"],["The controller request was cancelled.","控制器请求已取消。","控制器請求已取消。","コントローラーへのリクエストをキャンセルしました。","Запрос к контроллеру отменён.","Die Controller-Anfrage wurde abgebrochen.","La requête au contrôleur a été annulée.","Se canceló la solicitud al controlador."]],
[["flash_unsupported"],["Use desktop Chrome or Edge with Web Serial support.","请使用支持 Web Serial 的电脑端 Chrome 或 Edge。","請使用支援 Web Serial 的電腦版 Chrome 或 Edge。","Web Serial対応のデスクトップ版ChromeまたはEdgeを使用してください。","Используйте настольный Chrome или Edge с поддержкой Web Serial.","Verwenden Sie Chrome oder Edge auf einem Computer mit Web-Serial-Unterstützung.","Utilisez Chrome ou Edge sur ordinateur avec Web Serial.","Usa Chrome o Edge de escritorio con soporte para Web Serial."]],
[["flash_busy","flash_setup_busy"],["Another firmware or USB operation is running. Wait for it to finish and close other apps using this port.","另一个固件或 USB 操作正在进行。请等待完成，并关闭占用该串口的其他程序。","另一個韌體或 USB 操作正在進行。請等待完成，並關閉佔用該序列埠的其他程式。","別のファームウェアまたはUSB操作が実行中です。完了を待ち、このポートを使用する他のアプリを閉じてください。","Выполняется другая операция с прошивкой или USB. Дождитесь её завершения и закройте приложения, использующие этот порт.","Ein anderer Firmware- oder USB-Vorgang läuft. Warten Sie auf den Abschluss und schließen Sie andere Programme, die den Port verwenden.","Une autre opération de micrologiciel ou USB est en cours. Attendez sa fin et fermez les applications utilisant ce port.","Hay otra operación de firmware o USB en curso. Espera a que termine y cierra las aplicaciones que usen este puerto."]],
[["flash_manifest","flash_download","flash_integrity"],["Firmware could not be downloaded or verified. Reload the page and check the firmware source.","无法下载或校验固件。请刷新页面并检查固件来源。","無法下載或驗證韌體。請重新整理頁面並檢查韌體來源。","ファームウェアを取得または検証できません。ページを再読み込みし、配布元を確認してください。","Не удалось загрузить или проверить прошивку. Обновите страницу и проверьте источник прошивки.","Die Firmware konnte nicht geladen oder geprüft werden. Laden Sie die Seite neu und prüfen Sie die Firmware-Quelle.","Impossible de télécharger ou de vérifier le micrologiciel. Rechargez la page et vérifiez sa source.","No se pudo descargar o verificar el firmware. Recarga la página y comprueba su origen."]],
[["flash_chip_mismatch","flash_capacity"],["The selected firmware does not match the connected chip or its flash capacity. Choose the correct board with at least 4 MB flash.","所选固件与连接的芯片或闪存容量不匹配。请选择正确板型，并确保闪存至少为 4 MB。","所選韌體與連接的晶片或快閃記憶體容量不符。請選擇正確板型，並確認容量至少為 4 MB。","選択したファームウェアがチップまたは容量と一致しません。正しいボードを選び、フラッシュが4 MB以上あることを確認してください。","Прошивка не соответствует чипу или объёму памяти. Выберите правильную плату с флеш-памятью не менее 4 МБ.","Die Firmware passt nicht zum Chip oder zur Flash-Kapazität. Wählen Sie das richtige Board mit mindestens 4 MB Flash.","Le micrologiciel ne correspond pas à la puce ou à sa capacité. Choisissez la bonne carte avec au moins 4 Mo de mémoire flash.","El firmware no coincide con el chip o su capacidad. Elige la placa correcta con al menos 4 MB de memoria flash."]],
[["flash_dependency"],["The firmware installer could not initialize. Reload the page and try again.","固件安装组件无法初始化。请刷新页面后重试。","韌體安裝元件無法初始化。請重新整理頁面後再試。","ファームウェアのインストーラーを初期化できません。ページを再読み込みして再試行してください。","Не удалось запустить установщик прошивки. Обновите страницу и повторите попытку.","Der Firmware-Installer konnte nicht gestartet werden. Laden Sie die Seite neu und versuchen Sie es erneut.","Impossible de démarrer l’installation du micrologiciel. Rechargez la page et réessayez.","No se pudo iniciar el instalador de firmware. Recarga la página e inténtalo de nuevo."]],
[["flash_setup_invalid","flash_setup_timeout","flash_setup_closed"],["USB setup information could not be read or verified. Check the selected board and data cable, then try again.","无法读取或校验 USB 配置信息。请检查所选板卡和数据线，然后重试。","無法讀取或驗證 USB 設定資訊。請檢查所選開發板與資料線，然後再試。","USB設定情報を読み取るか検証できません。選択したボードとデータケーブルを確認して再試行してください。","Не удалось прочитать или проверить настройки USB. Проверьте выбранную плату и кабель данных и повторите попытку.","Die USB-Einrichtungsdaten konnten nicht gelesen oder geprüft werden. Prüfen Sie Board und Datenkabel und versuchen Sie es erneut.","Impossible de lire ou de vérifier la configuration USB. Vérifiez la carte sélectionnée et le câble de données, puis réessayez.","No se pudo leer o verificar la configuración USB. Comprueba la placa seleccionada y el cable de datos e inténtalo de nuevo."]],
[["CONTEXT_WINDOW_EXCEEDED"],["This conversation exceeds the model’s context window. Enable automatic compaction or choose a model with a larger context window.","会话超出模型的上下文长度，请开启自动压缩或换用支持更长上下文的模型。","對話超出模型的上下文長度，請啟用自動壓縮或改用支援更長上下文的模型。","会話がモデルのコンテキスト上限を超えています。自動圧縮を有効にするか、上限の大きいモデルを選んでください。","Чат превышает окно контекста модели. Включите автоматическое сжатие или выберите модель с большим окном.","Die Sitzung überschreitet das Kontextfenster des Modells. Aktivieren Sie die automatische Komprimierung oder wählen Sie ein Modell mit größerem Kontextfenster.","La conversation dépasse la fenêtre de contexte du modèle. Activez la réduction automatique ou choisissez un modèle acceptant un contexte plus long.","La conversación supera la ventana de contexto del modelo. Activa la reducción automática o elige un modelo con una ventana mayor."]],
[["CAPTURE_IMAGE_TOO_LARGE"],["This JPEG is still too large. Choose a lower image quality in Settings and try again.","JPEG 图片仍然过大，请在设置中选择更低的图片质量后重试。","JPEG 圖片仍然過大，請在設定中選擇較低的圖片品質後重試。","JPEG画像が大きすぎます。設定で画質を下げて再試行してください。","Изображение JPEG слишком большое. Выберите более низкое качество в настройках и повторите попытку.","Das JPEG-Bild ist noch zu groß. Wählen Sie in den Einstellungen eine niedrigere Bildqualität und versuchen Sie es erneut.","L’image JPEG est encore trop volumineuse. Choisissez une qualité inférieure dans les réglages et réessayez.","El JPEG sigue siendo demasiado grande. Selecciona una calidad menor en Ajustes e inténtalo de nuevo."]],
[["STORE_CLOSED"],["Local storage is unavailable. Reload the page and try again.","暂时无法访问设备上的数据，请刷新页面后重试。","暫時無法存取裝置上的資料，請重新整理頁面後再試。","端末のデータにアクセスできません。ページを再読み込みして再試行してください。","Локальные данные недоступны. Обновите страницу и повторите попытку.","Lokale Daten sind nicht erreichbar. Laden Sie die Seite neu und versuchen Sie es erneut.","Les données locales sont indisponibles. Rechargez la page et réessayez.","Los datos locales no están disponibles. Recarga la página e inténtalo de nuevo."]],
[["STORE_VERSION_CHANGED"],["The local database was updated. Reload this page to continue.","本地数据已更新，请刷新页面后继续。","本機資料已更新，請重新整理頁面後繼續。","ローカルデータが更新されました。ページを再読み込みしてください。","Локальная база данных обновлена. Перезагрузите страницу.","Die lokale Datenbank wurde aktualisiert. Laden Sie die Seite neu.","La base de données locale a été mise à jour. Rechargez cette page.","La base de datos local se ha actualizado. Recarga la página para continuar."]],
[["DEVICE_WINDOW_BLOCKED"], ["Allow this site to open the device connection window, then try again.", "请允许网站打开设备连接窗口，然后重试。", "請允許網站開啟裝置連線視窗，然後重試。", "デバイス接続ウィンドウを開けるようにして、再試行してください。", "Разрешите сайту открыть окно подключения устройства и повторите попытку.", "Erlaube das Geräte-Verbindungsfenster und versuche es erneut.", "Autorisez l’ouverture de la fenêtre de connexion, puis réessayez.", "Permite que el sitio abra la ventana de conexión y vuelve a intentarlo."]],
[["DEVICE_WINDOW_NOT_READY"], ["Keep the device connection window open and return to Harness.", "请保留设备连接窗口，并切回 Harness。", "請保留裝置連線視窗，並切回 Harness。", "接続ウィンドウを開いたまま Harness に戻ってください。", "Оставьте окно подключения открытым и вернитесь в Harness.", "Lass das Verbindungsfenster geöffnet und kehre zu Harness zurück.", "Gardez la fenêtre de connexion ouverte et revenez à Harness.", "Deja abierta la ventana de conexión y vuelve a Harness."]],
[["DEVICE_WINDOW_CLOSED", "DEVICE_WINDOW_RELOADED"], ["The device connection window closed or reloaded. Connect the device again.", "设备连接窗口已关闭或刷新，请重新连接设备。", "裝置連線視窗已關閉或重新載入，請重新連接裝置。", "接続ウィンドウが閉じたか再読み込みされました。再接続してください。", "Окно подключения закрыто или перезагружено. Подключите устройство заново.", "Das Verbindungsfenster wurde geschlossen oder neu geladen. Verbinde das Gerät erneut.", "La fenêtre de connexion a été fermée ou rechargée. Reconnectez l’appareil.", "La ventana de conexión se cerró o recargó. Vuelve a conectar el dispositivo."]],
[["DEVICE_WINDOW_REQUEST_FAILED", "DEVICE_WINDOW_TIMEOUT"], ["No reply from the device. Check that it is online and reconnect.", "未收到设备回复，请确认设备在线后重新连接。", "未收到裝置回覆，請確認裝置在線後重新連接。", "デバイスから応答がありません。接続を確認して再接続してください。", "Устройство не ответило. Проверьте подключение и подключитесь заново.", "Keine Antwort vom Gerät. Prüfe die Verbindung und verbinde es erneut.", "L’appareil ne répond pas. Vérifiez sa connexion et reconnectez-le.", "El dispositivo no responde. Comprueba la conexión y vuelve a conectarlo."]]
];
export const ERROR_CATALOG=Object.fromEntries(rows.flatMap(([aliases,texts])=>aliases.map(alias=>[alias,Object.fromEntries(locales.map((locale,i)=>[locale,texts[i]]))])));
Object.assign(ERROR_CATALOG,HARNESS_RETURN_ERRORS);
